+            // disabled, so enabling it raises that interrupt rather than losing the message.
+            _leaf_guard: tree.enable_leaf_guarded(
+                GSP_INTR_0_VECTOR.leaf_index(),
+                GSP_INTR_0_VECTOR.leaf_mask(),
+            ),
+        })
+    }
+}
